import { Command } from 'commander';
import crypto from 'crypto';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { git } from '../utils/git.js';

const stashDir = path.join(os.homedir(), '.gitcli', 'secure-stash');

function encrypt(data: string, password: string) {
  const iv = crypto.randomBytes(16);
  const key = crypto.createHash('sha256').update(password).digest();
  const cipher = crypto.createCipheriv('aes-256-ctr', key, iv);
  const encrypted = Buffer.concat([cipher.update(data, 'utf8'), cipher.final()]);
  return iv.toString('hex') + ':' + encrypted.toString('hex');
}

export function registerStash(program: Command) {
  program
    .command('stash')
    .description('Secure git stash with AES-256')
    .option('--secure', 'Encrypt stash contents')
    .option('-p, --password <password>', 'Encryption password')
    .action(async opts => {
      const gitClient = git();
      if (!opts.secure) {
        await gitClient.raw(['stash']);
        console.log('Stashed using git.');
        return;
      }
      const password = opts.password || process.env.GITCLI_STASH_KEY || 'gitcli';
      const diff = await gitClient.diff(['--staged', '--cached', '--full-index']);
      if (!fs.existsSync(stashDir)) fs.mkdirSync(stashDir, { recursive: true });
      const file = path.join(stashDir, `${Date.now()}.stash`);
      fs.writeFileSync(file, encrypt(diff, password));
      await gitClient.reset(['--hard']);
      console.log('Secure stash stored at', file);
    });
}
